import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class GorePatch implements Opcodes {
 public static void main(String[] args)throws Exception{Map<String,byte[]> entries=new TreeMap<>();try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();if(e.getName().equals("dev/zomboid/gore/Rules.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("crawling")){InsnList x=new InsnList();LabelNode next=new LabelNode();x.add(new VarInsnNode(ILOAD,0));x.add(new LdcInsnNode(1<<30));x.add(new InsnNode(IAND));x.add(new JumpInsnNode(IFEQ,next));x.add(new InsnNode(ICONST_1));x.add(new InsnNode(IRETURN));x.add(next);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}else if(e.getName().equals("dev/zomboid/gore/Gore.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("tick")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/gore/Knockdown18","tick","(Ljava/lang/Object;)V",false));m.instructions.insert(x);for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof LdcInsnNode n&&Integer.valueOf(0x30000030).equals(n.cst))n.cst=0x70000030;}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}if(e.getName().equals("META-INF/neoforge.mods.toml"))b=new String(b,java.nio.charset.StandardCharsets.UTF_8).replace("version=\"1.0.7\"","version=\"1.0.8\"").getBytes(java.nio.charset.StandardCharsets.UTF_8);entries.put(e.getName(),b);}}try(var walk=Files.walk(Path.of(args[2]))){for(Path p:walk.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}for(var e:entries.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}}
}
